package com.example.starter.germination.domain;

/**
 * 发芽率检测记录状态。
 * <ul>
 *     <li>{@link #VALID}：有效检测，可参与证书签发判定；</li>
 *     <li>{@link #VOID}：取样记录已作废，仅作历史留存，不再支撑任何证书。</li>
 * </ul>
 */
public enum TestStatus {
    /** 有效。 */
    VALID,
    /** 已作废（不可恢复，历史保留）。 */
    VOID
}

package com.example.starter.germination.domain;

/**
 * 发芽率证书状态。
 * <ul>
 *     <li>{@link #VALID}：当前有效，仓储可据此放行；已放行批次的证书始终保持该状态作为快照；</li>
 *     <li>{@link #INVALID}：证书未放行时，其固化的检测记录被作废导致失效，不能再用于放行。</li>
 * </ul>
 */
public enum CertificateStatus {
    /** 有效（含已放行批次留存的证书快照）。 */
    VALID,
    /** 未放行即因检测作废而失效。 */
    INVALID
}

package com.example.starter.germination.domain;

import java.time.Instant;

/**
 * 种子批次（合成批次数据）。
 *
 * @param batchNo   批次编号，业务主键
 * @param cropName  作物名称
 * @param createdAt 入库时刻（UTC 时间线，序列化按 Asia/Shanghai 展示）
 */
public record SeedBatch(String batchNo, String cropName, Instant createdAt) {
}

package com.example.starter.germination.domain;

import java.time.Instant;

/**
 * 单次发芽率检测记录（复检亦为追加的新记录，历史记录不被修改）。
 *
 * @param testNo           检测编号，全库唯一，同一编号只能归属一个批次
 * @param batchNo          所属种子批次编号
 * @param sampleCount      样本数，单位粒，合法区间 100-400
 * @param germinatedCount  发芽粒数，单位粒，满足 0 ≤ germinatedCount ≤ sampleCount
 * @param status           记录状态：VALID 有效 / VOID 已作废
 * @param recordedAt       检测登记时刻（UTC 时间线），复检按追加时间排序
 * @param voidedAt         作废时刻；null 表示尚未作废
 */
public record GerminationTest(String testNo,
                              String batchNo,
                              int sampleCount,
                              int germinatedCount,
                              TestStatus status,
                              Instant recordedAt,
                              Instant voidedAt) {

    /**
     * 发芽比例（百分数），例如 86 粒 / 100 粒 = 86.00。
     *
     * @return 发芽率百分数，单位 %，保留两位小数
     */
    public java.math.BigDecimal ratioPercent() {
        return java.math.BigDecimal.valueOf(germinatedCount)
                .multiply(java.math.BigDecimal.valueOf(100))
                .divide(java.math.BigDecimal.valueOf(sampleCount), 2, java.math.RoundingMode.HALF_UP);
    }
}

package com.example.starter.germination.domain;

import java.time.Instant;

/**
 * 批次放行事实；一旦生成即历史事实，不因后续检测作废而回滚。
 *
 * @param batchNo     被放行的种子批次编号（主键，一个批次至多放行一次）
 * @param certNo      放行时依据的证书编号（证书快照外键）
 * @param releasedAt  放行时刻（UTC 时间线）
 */
public record BatchRelease(String batchNo, String certNo, Instant releasedAt) {
}

