package com.example.starter.germination.web;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 登记一次发芽率检测（取样检测/复检追加）请求。
 *
 * @param testNo           检测编号，全库唯一
 * @param batchNo          所属种子批次编号
 * @param sampleCount      样本数，单位粒，100-400
 * @param germinatedCount  发芽粒数，单位粒，不得超过样本数
 * @param requestId        幂等请求号；同号同参重放返回首次结果，异参返回 409
 */
public record RegisterTestRequest(@NotBlank String testNo,
                                  @NotBlank String batchNo,
                                  @NotNull @Min(100) @Max(400) Integer sampleCount,
                                  @NotNull @Min(0) Integer germinatedCount,
                                  @NotBlank String requestId) {
}

package com.example.starter.germination.web;

import jakarta.validation.constraints.NotBlank;

/**
 * 作废一条取样检测记录请求。
 *
 * @param testNo     待作废检测编号
 * @param batchNo    所属批次编号（防止跨批次操作）
 * @param requestId  幂等请求号
 */
public record VoidTestRequest(@NotBlank String testNo,
                              @NotBlank String batchNo,
                              @NotBlank String requestId) {
}

package com.example.starter.germination.web;

import jakarta.validation.constraints.NotBlank;

/**
 * 签发发芽率证书请求；依据该批次最近两次有效检测。
 *
 * @param batchNo    所属种子批次编号
 * @param requestId  幂等请求号；同号同参重放返回首次证书，异参 409
 */
public record IssueCertificateRequest(@NotBlank String batchNo,
                                      @NotBlank String requestId) {
}

package com.example.starter.germination.web;

import jakarta.validation.constraints.NotBlank;

/**
 * 批次放行请求；仅可凭有效证书放行对应批次。
 *
 * @param batchNo    请求放行的批次编号
 * @param requestId  幂等请求号；同号同参重放返回首次放行结果，异参 409
 */
public record ReleaseBatchRequest(@NotBlank String batchNo,
                                  @NotBlank String requestId) {
}

package com.example.starter.germination.service;

/**
 * 业务拒绝原因编码，随 4xx 响应返回，便于调用方明确区分拒绝原因。
 */
public enum RejectReason {
    /** 批次不存在。 */
    BATCH_NOT_FOUND,
    /** 样本数不在 100-400 区间。 */
    SAMPLE_OUT_OF_RANGE,
    /** 发芽粒数超过样本数或为负。 */
    GERMINATED_EXCEEDS_SAMPLE,
    /** 检测编号不存在。 */
    TEST_NOT_FOUND,
    /** 检测编号已归属其他批次（同一检测编号只归属一个批次）。 */
    TEST_BELONGS_TO_OTHER_BATCH,
    /** 检测记录已作废，重复作废或不能再使用。 */
    TEST_ALREADY_VOID,
    /** 有效检测不足两次，不能签发证书。 */
    NOT_ENOUGH_VALID_TESTS,
    /** 最近两次有效检测存在发芽率低于 85% 的记录。 */
    RATIO_BELOW_THRESHOLD,
    /** 该批次已存在证书（证书不可覆盖，含失效证书）。 */
    CERTIFICATE_ALREADY_EXISTS,
    /** 证书不存在，不能放行。 */
    CERTIFICATE_NOT_FOUND,
    /** 证书已失效，放行冲突。 */
    CERTIFICATE_INVALID,
    /** 批次已放行，操作冲突。 */
    BATCH_ALREADY_RELEASED,
    /** 同一 requestId 重放但请求参数与首次不一致。 */
    IDEMPOTENT_PARAM_MISMATCH
}

package com.example.starter.germination.service;

/**
 * 业务规则被违反时抛出；映射为 HTTP 422。
 */
public class BusinessRejectedException extends RuntimeException {

    private final RejectReason reason;

    public BusinessRejectedException(RejectReason reason, String message) {
        super(message);
        this.reason = reason;
    }

    public RejectReason getReason() {
        return reason;
    }
}

package com.example.starter.germination.service;

import org.springframework.http.HttpStatus;

/**
 * 请求与当前资源状态冲突（如失效证书放行、幂等异参、批次已放行）；映射为 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    private final RejectReason reason;
    private final HttpStatus status;

    public ConflictException(RejectReason reason, String message) {
        this(reason, message, HttpStatus.CONFLICT);
    }

    public ConflictException(RejectReason reason, String message, HttpStatus status) {
        super(message);
        this.reason = reason;
        this.status = status;
    }

    public RejectReason getReason() {
        return reason;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.germination.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 发芽率业务规则（无状态，便于单元测试）。
 */
public final class GerminationRules {

    /** 样本数下限，单位粒。 */
    public static final int MIN_SAMPLE = 100;
    /** 样本数上限，单位粒。 */
    public static final int MAX_SAMPLE = 400;
    /** 签发证书要求的发芽率下限，单位 %。 */
    public static final BigDecimal PASS_RATIO = new BigDecimal("85.00");

    private GerminationRules() {
    }

    /**
     * 样本数是否合法（100-400 粒）。
     */
    public static boolean isSampleCountValid(int sampleCount) {
        return sampleCount >= MIN_SAMPLE && sampleCount <= MAX_SAMPLE;
    }

    /**
     * 发芽粒数是否合法（非负且不超过样本数）。
     */
    public static boolean isGerminatedCountValid(int sampleCount, int germinatedCount) {
        return germinatedCount >= 0 && germinatedCount <= sampleCount;
    }

    /**
     * 计算发芽率百分数，保留两位小数，四舍五入。
     */
    public static BigDecimal ratioPercent(int sampleCount, int germinatedCount) {
        return BigDecimal.valueOf(germinatedCount)
                .multiply(BigDecimal.valueOf(100))
                .divide(BigDecimal.valueOf(sampleCount), 2, RoundingMode.HALF_UP);
    }

    /**
     * 单次检测是否达到签发要求（发芽率 ≥ 85%）。
     */
    public static boolean isPassing(int sampleCount, int germinatedCount) {
        return ratioPercent(sampleCount, germinatedCount).compareTo(PASS_RATIO) >= 0;
    }
}

