        // 跨批次引用同一检测编号
        assertThatThrownBy(() -> service.registerTest(reg(TAG + "R3", TAG + "T1", TAG + "B2", 100, 90)))
                .isInstanceOfSatisfying(BusinessRejectedException.class, ex ->
